/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  const n = parseInt(line);

  let print = 1; // 每行要打印的数，起始为第一行第一个数1
  for (let i = 1; i <= n; i++) { // 多少行
    let printList = [];
    for (let j = 0; j < i; j++) { // 每行多少个数
      printList.push(print++);
    }
    if (i % 2 === 0) { // 如果是偶数行，则逆序
      printList.reverse();
    }
    printList = printList.map((ele) => { // 如果数字不足4位则后面用*补足
      let arr = (ele + "").split("");

      while (arr.length < 4) {
        arr.push("*");
      }

      return arr.join("");
    });

    let res = [];
    res.push(printList.join("    "));
    for (let m = 0; m < n - i; m++) { // 每行的缩进
      res.unshift("    ");
    }
    console.log(res.join(""));
  }
});
